int oblicz_ONP(string wyr) {
    int stos[100];
    int top = -1;
    for (int i = 0; i < wyr.length(); i++) {
        if (wyr[i] >= '0' && wyr[i] <= '9') {
            stos[++top] = wyr[i] - '0';
        } else if (wyr[i] == '+' || wyr[i] == '-' || wyr[i] == '*') {
            int b = stos[top--];
            int a = stos[top--];
            if (wyr[i] == '+') stos[++top] = a + b;
            else if (wyr[i] == '-') stos[++top] = a - b;
            else stos[++top] = a * b;
        }
    }
    return stos[0];
}
```

**Weryfikacja**:
- "3 4 + 2 *": push 3, push 4, '+': pop 4,3 → push 7, push 2, '*': pop 2,7 → push 14 → 14 ✓
- "5 2 - 3 +": push 5, push 2, '-': pop 2,5 → push 3, push 3, '+': pop 3,3 → push 6 → 6 ✓
- "2 3 * 4 +": push 2, push 3, '*': pop 3,2 → push 6, push 4, '+': pop 4,6 → push 10 → 10 ✓
